@@ -1,19 +1,72 @@
+import * as fs from "fs";
+import * as path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

 const store = new Map<string, Entry>();
+const cacheDir = process.env.CACHE_DIR || "/tmp/app-session-cache";
+
+const ensureCacheDir = (): void => {
+  if (!fs.existsSync(cacheDir)) {
+    fs.mkdirSync(cacheDir, { recursive: true });
+  }
+};
+
+const getCachePath = (key: string): string => {
+  const hash = key.replace(/[^a-zA-Z0-9-]/g, "_");
+  return path.join(cacheDir, `${hash}.json`);
+};
+
+const loadFromDisk = (key: string): Entry | null => {
+  try {
+    const filePath = getCachePath(key);
+    if (!fs.existsSync(filePath)) return null;
+    const data = fs.readFileSync(filePath, "utf-8");
+    return JSON.parse(data);
+  } catch {
+    return null;
+  }
+};
+
+const saveToDisk = (key: string, entry: Entry): void => {
+  try {
+    ensureCacheDir();
+    const filePath = getCachePath(key);
+    fs.writeFileSync(filePath, JSON.stringify(entry));
+  } catch (err) {
+    console.error(`Failed to persist key ${key}:`, err);
+  }
+};
+
+ensureCacheDir();

 export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  const entry = { value, expiresAt: Date.now() + ttlMs };
+  store.set(key, entry);
+  saveToDisk(key, entry);
 };

 export const get = (key: string): string | null => {
-  const entry = store.get(key);
+  let entry = store.get(key);
+
+  if (entry === undefined) {
+    entry = loadFromDisk(key);
+    if (entry !== null) {
+      store.set(key, entry);
+    }
+  }
+
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
     store.delete(key);
+    try {
+      fs.unlinkSync(getCachePath(key));
+    } catch {
+      // File may not exist
+    }
     return null;
   }
   return entry.value;
